from mlmodelscope.pytorch_agent.models.pytorch_abc import PyTorchAbstractClass

from open_clip import create_model_from_pretrained, get_tokenizer
from PIL import Image
import torch

class PyTorch_Transformers_MarqoFashionCLIP(PyTorchAbstractClass):
    def __init__(self, config=None):
        self.config = config if config else dict()
        device = self.config.pop("_device", "cpu")
        multi_gpu = self.config.pop("_multi_gpu", False)

        model_id = "Marqo/marqo-fashionCLIP"
        # Use open_clip directly to avoid transformers/accelerate meta device issues
        # Config points to hf-hub:Marqo/marqo-fashionCLIP
        self.model, self.image_preprocessor = create_model_from_pretrained('hf-hub:Marqo/marqo-fashionCLIP')
        self.tokenizer = get_tokenizer('hf-hub:Marqo/marqo-fashionCLIP')
        
        self.model.to(device)
        self.doc_device = device 
        self.model.eval()

        # For zero-shot classification, labels must be provided to compute text features
        self.labels = self.config.get("labels",[])
        if not self.labels or not isinstance(self.labels, list):
            features_file_url = "http://s3.amazonaws.com/store.carml.org/synsets/imagenet/synset.txt"
            self.labels = self.features_download(features_file_url)

        self.text_features = None
        if self.labels:
            # Tokenizer returns a tensor [batch_size, context_length]
            text_tokens = self.tokenizer(self.labels)
            
            input_device = next(self.model.parameters()).device
            input_ids = text_tokens.to(input_device)
            
            with torch.no_grad():
                self.text_features = self.model.encode_text(input_ids, normalize=True)
                
    def to(self, device, multi_gpu=False):
         # Override parent to method
         self.model.to(device)
         self.doc_device = device
         if self.text_features is not None:
             self.text_features = self.text_features.to(device)

    def preprocess(self, input_images):
        processed_images = [
            self.image_preprocessor(Image.open(image_path).convert('RGB'))
            for image_path in input_images
        ]
        # Stack images into a single tensor [batch_size, channels, height, width]
        pixel_values = torch.stack(processed_images)
        return {'pixel_values': pixel_values}

    def predict(self, model_input):
        input_device = next(self.model.parameters()).device
        pixel_values = model_input['pixel_values'].to(input_device)
        with torch.no_grad():
            # Using open_clip encode_image
            image_features = self.model.encode_image(pixel_values, normalize=True)
        return image_features

    def postprocess(self, model_output):
        if self.text_features is None or self.text_features.shape[0] == 0:
            raise ValueError("Labels were not provided during initialization for this zero-shot model.")

        # model_output from predict() is the image_features tensor
        # Calculate similarity between image features and pre-computed text features
        logits_per_image = 100.0 * model_output @ self.text_features.T
        probabilities = logits_per_image.softmax(dim=-1)
        return probabilities.cpu().tolist()
